{
  "state_facts": [],
  "guidance_facts": [
    {
      "statement": "Reducing total fat intake can lead to a decrease in total energy intake, which may result in weight loss.",
      "citations": ["who-guideline-4f47a8d684098dc3c22b7ad5"]
    },
    {
      "statement": "Infants should be exclusively breastfed for the first 6 months of life to achieve optimal growth, development, and health.",
      "citations": ["who-guideline-4f47a8d684098dc3c22b7ad5"]
    },
    {
      "statement": "The guideline focuses on preventing unhealthy weight gain, not managing existing overweight or obesity.",
      "citations": ["who-guideline-4f47a8d684098dc3c22b7ad5"]
    },
    {
      "statement": "Lower fat, restricted-calorie diets may be effective for short-term weight loss in individuals actively pursuing weight loss.",
      "citations": ["who-guideline-4f47a8d684098dc3c22b7ad5"]
    }
  ]
}

{
  "state_facts": [],
  "guidance_facts": [
    {
      "statement": "The recommendation emphasizes that reducing total fat intake alone is not sufficient to prevent unhealthy weight gain.",
      "citations": ["who-guideline-33511bbfac7ce4586cb7aadc"]
    },
    {
      "statement": "Total fat intake should be at least 15–20% of total energy intake to ensure adequate energy and essential fatty acids.",
      "citations": ["who-guideline-33511bbfac7ce4586cb7aadc"]
    },
    {
      "statement": "The implementation of this recommendation must consider individual energy requirements and avoid excess energy intake.",
      "citations": ["who-guideline-33511bbfac7ce4586cb7aadc"]
    },
    {
      "statement": "In populations where undernutrition is a concern, maintaining or increasing total fat intake may be important to achieve adequate energy intake.",
      "citations": ["who-guideline-33511bbfac7ce4586cb7aadc"]
    }
  ]
}

{
  "state_facts": [],
  "guidance_facts": [
    {
      "statement": "All adults living with disability should undertake regular physical activity.",
      "citations": ["who-guideline-e6e84b1a717d8c85db5f0454"]
    },
    {
      "statement": "Adults living with disability should do at least 150–300 minutes of moderate-intensity aerobic physical activity or an equivalent combination of moderate- and vigorous-intensity activity throughout the week.",
      "citations": ["who-guideline-e6e84b1a717d8c85db5f0454"]
    },
    {
      "statement": "Adults living with disability should also do muscle-strengthening activities at moderate or greater intensity that involve all major muscle groups on 2 or more days a week.",
      "citations": ["who-guideline-e6e84b1a717d8c85db5f0454"]
    },
    {
      "statement": "Older adults living with disability should do varied multicomponent physical activity that emphasizes functional balance and strength training at moderate or greater intensity on 3 or more days a week to enhance functional capacity and prevent falls.",
      "citations": ["who-guideline-e6e84b1a717d8c85db5f0454"]
    }
  ]
}

{
  "state_facts": [],
  "guidance_facts": [
    {
      "statement": "Older adults should engage in at least 150–300 minutes of moderate-intensity aerobic physical activity weekly.",
      "citations": ["who-guideline-9c2ad627f2731d22c33e010d"]
    },
    {
      "statement": "Older adults should also perform muscle-strengthening activities involving all major muscle groups on 2 or more days a week.",
      "citations": ["who-guideline-9c2ad627f2731d22c33e010d"]
    },
    {
      "statement": "Varied multicomponent physical activity emphasizing functional balance and strength training should be done on 3 or more days a week to enhance functional capacity and prevent falls.",
      "citations": ["who-guideline-9c2ad627f2731d22c33e010d"]
    },
    {
      "statement": "Older adults may increase aerobic activity beyond 300 minutes of moderate-intensity or 150 minutes of vigorous-intensity for additional health benefits.",
      "citations": ["who-guideline-9c2ad627f2731d22c33e010d"]
    }
  ]
}

{
  "state_facts": [],
  "guidance_facts": [
    {
      "statement": "WHO recommends that adults limit total fat intake to 30% of total energy intake or less to reduce the risk of unhealthy weight gain.",
      "citations": ["who-guideline-5f9f38ca0abb571b9420ada2"]
    },
    {
      "statement": "This recommendation is specifically relevant for individuals aged 20 years or older.",
      "citations": ["who-guideline-5f9f38ca0abb571b9420ada2"]
    },
    {
      "statement": "The evidence was considered insufficient to support the formulation of a recommendation for children due to limited studies and inconsistent results.",
      "citations": ["who-guideline-5f9f38ca0abb571b9420ada2"]
    },
    {
      "statement": "For children aged 6 months and above and adolescents, total fat intakes of up to 35% of total energy are appropriate to meet growth demands without leading to excess energy intake.",
      "citations": ["who-guideline-5f9f38ca0abb571b9420ada2"]
    }
  ]
}

{
  "state_facts": [],
  "guidance_facts": [
    {
      "statement": "The WHO guideline suggests that cardiovascular risk assessment should be conducted at or after the initiation of pharmacological treatment for hypertension.",
      "citations": ["who-guideline-a88b56abfce6c49800316477"]
    },
    {
      "statement": "Cardiovascular risk assessment is most important for guiding decisions about initiating pharmacological treatment for hypertension in those with lower SBP (130–139 mmHg).",
      "citations": ["who-guideline-a88b56abfce6c49800316477"]
    },
    {
      "statement": "CVD risk assessment is critical in those with HTN that other risk factors must be identified and treated appropriately to lower total cardiovascular risk.",
      "citations": ["who-guideline-a88b56abfce6c49800316477"]
    },
    {
      "statement": "In the absence of a calibrated equation for the local population, the choice of CVD risk-assessment systems should depend on resources available, acceptability, and feasibility of application.",
      "citations": ["who-guideline-a88b56abfce6c49800316477"]
    }
  ]
}

{
  "state_facts": [],
  "guidance_facts": [
    {
      "statement": "The WHO recommends initiating pharmacological antihypertensive treatment for individuals with a confirmed diagnosis of hypertension and systolic blood pressure of ≥140 mmHg or diastolic blood pressure of ≥90 mmHg.",
      "citations": ["who-guideline-7f385b69c8e66434d2fefc4c"]
    },
    {
      "statement": "For individuals with existing cardiovascular disease, the WHO recommends pharmacological treatment if systolic blood pressure is 130–139 mmHg.",
      "citations": ["who-guideline-7f385b69c8e66434d2fefc4c"]
    },
    {
      "statement": "The WHO suggests pharmacological treatment for individuals without cardiovascular disease but with high cardiovascular risk, diabetes mellitus, or chronic kidney disease, and systolic blood pressure of 130–139 mmHg.",
      "citations": ["who-guideline-7f385b69c8e66434d2fefc4c"]
    },
    {
      "statement": "Pharmacological treatment for hypertension should start no later than four weeks following diagnosis, and earlier if blood pressure is very high or there is evidence of end organ damage.",
      "citations": ["who-guideline-7f385b69c8e66434d2fefc4c"]
    }
  ]
}

{
  "state_facts": [],
  "guidance_facts": [
    {
      "statement": "Pharmacological treatment of hypertension can be provided by nonphysician professionals such as pharmacists and nurses.",
      "citations": ["who-guideline-5ca2f3d427b204da9c293c0f"]
    },
    {
      "statement": "Nonphysician professionals must have proper training, prescribing authority, specific management protocols, and physician oversight.",
      "citations": ["who-guideline-5ca2f3d427b204da9c293c0f"]
    },
    {
      "statement": "Community health care workers may assist in tasks such as education, delivery of medications, blood pressure measurement, and monitoring through a collaborative care model.",
      "citations": ["who-guideline-5ca2f3d427b204da9c293c0f"]
    },
    {
      "statement": "Telemonitoring and community or home-based self-care are encouraged to enhance blood pressure control as part of an integrated management system.",
      "citations": ["who-guideline-5ca2f3d427b204da9c293c0f"]
    }
  ]
}

